window.products.push({"id":351109,"name":"Best Choice Products 4in Portable Mattress Folding Mattress Topper Full for Camping, Guest, Toddler, Foam Plush w/Carry Case - Gray","category":"homeandappliances","retail price":149.99,"sale price":null,"image":"https://m.media-amazon.com/images/I/91jBj+uhjvL._AC_SL1500_.jpg","description":"4IN PLUSH FOAM: Soft yet firm foam provides maximum comfort and padding while protecting your mattress from dirt, pet fur, dead skin, and other pollutants MULTIPURPOSE: Great as a convenient guest bed, a comfy camping bed, or as a floor sofa during movie nights and gatherings with friends and family PORTABLE AND SPACE-SAVING: Simply slip the included carrying case over the portable, tri-fold mattress and zip it up to keep it neat and secure while you travel EASY SETUP: Open package in well-ventilated area to release harmless odor that should dissipate within several hours. Wait 24-72 hours for maximum expansion SUGGESTED MAINTENANCE: To wash and care for the cover, spot clean with a damp cloth using cold water and mild soap before wiping dry with a dry cloth","images":["https://m.media-amazon.com/images/I/91jBj+uhjvL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Best Choice Products","source_asin":"B01INZBBMO","category_path":"Home & Kitchen"},"sku":"BM-351109","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B01INZBBMO","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B01INZBBMO","price_pending":true,"merchant_ready":false});
